global.after:
@custom-variant dark (&:where(.dark, .dark *));
* { box-sizing: border-box; scrollbar-width: none; }
*::-webkit-scrollbar { display: none; }
/* Anchor spacing belongs to document sections. Root scroll padding also
   affects portaled options and can scroll their page while a menu opens. */
body { margin: 0; background: var(--surface-base); color: var(--text-main); font-family: var(--font-inter), -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; -webkit-font-smoothing: antialiased; font-kerning: normal; }
button, input { font: inherit; }
button { cursor: pointer; }
a { color: inherit; text-decoration: none; }
::selection { color: white; background: var(--accent-strong); }
:focus-visible { outline: 1px solid var(--focus-ring); outline-offset: -2px; }
:where(:focus-visible, [data-focus-visible]) { outline-color: var(--focus-ring) !important; outline-width: 1px !important; outline-offset: -2px !important; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; }
}
:root { --font-inter: "Inter Variable"; --font-mono-source: "JetBrains Mono Variable"; }

