.ui-theme-transitioning::view-transition-new(root) {
  z-index: 2;
  mask-image: var(--theme-reveal-mask);
  mask-repeat: no-repeat;
  animation: ui-theme-reveal 820ms cubic-bezier(.16,1,.3,1) both;
  transform-origin: var(--theme-reveal-x) var(--theme-reveal-y);
}

@keyframes ui-theme-reveal {
  from { mask-position: var(--theme-reveal-x) var(--theme-reveal-y); mask-size: 0 0; }
  to { mask-position: var(--theme-reveal-left) var(--theme-reveal-top); mask-size: var(--theme-reveal-size) var(--theme-reveal-size); }
}

