.ui-button {
  position: relative;
  isolation: isolate;
  border: 0 solid transparent;
  color: var(--text-main);
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  letter-spacing: normal;
  transition: background-color var(--motion-fast) ease, border-color var(--motion-fast) ease, color var(--motion-fast) ease, box-shadow var(--motion-fast) ease, opacity var(--motion-fast) ease, transform var(--motion-standard) var(--motion-ease-soft);
}

.ui-template-browser__tab {
  display: flex;
  align-items: center;
  gap: 7px;
  align-self: end;
  width: min(190px, 35%);
  height: 31px;
  overflow: hidden;
  padding: 0 11px;
  border: 1px solid var(--border-subtle);
  border-bottom: 0;
  border-radius: 9px 9px 0 0;
  background: var(--surface-base);
  color: var(--text-main);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ui-ai-chat {
  --chat-sidebar-width: 242px;
  --chat-panel-width: 330px;
  position: relative;
  display: grid;
  grid-template-columns: var(--chat-sidebar-width) minmax(0, 1fr) 12px var(--chat-resized-panel-width,var(--chat-panel-width));
  gap: 0;
  width: 100%;
  height: 760px;
  min-width: 0;
  padding: 10px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
  border-radius: 21px;
  background: var(--surface-base);
  color: var(--text-main);
  font-size: 13px;
  line-height: 18px;
  transition: grid-template-columns var(--motion-standard) var(--motion-ease), column-gap var(--motion-standard) var(--motion-ease);
}

.ui-calendar {
  position: relative;
  width: 100%;
  padding: 16px;
  overflow: visible;
  border: 1px solid var(--border-subtle);
  border-radius: 22px;
  background: var(--surface-base);
  box-shadow: var(--shadow-control);
}

.ui-calendar__head {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 36px;
  padding: 0 1px 10px;
}

.ui-calendar__head h2 {
  flex: 1;
  min-width: 0;
  margin: 0;
  color: var(--text-strong);
  font-size: var(--text-title-2-medium);
  line-height: var(--text-title-2-medium--line-height);
  font-weight: var(--text-title-2-medium--font-weight);
  letter-spacing: var(--text-title-2-medium--letter-spacing);
}

.ui-calendar__tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  width: min(320px, 33vw);
  height: 36px;
  padding: 3px 5px;
  border: 1px solid var(--border-control);
  border-radius: 10px;
  background: var(--surface-base);
  box-shadow: var(--shadow-control);
}

.ui-calendar__tools button {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: none;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-strong);
  transition: background .18s ease, transform .18s ease;
}

.ui-calendar__new {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 12px;
  border: 0;
  border-radius: 10px;
  background: var(--accent-strong);
  color: white;
  font-size: var(--text-body-medium);
  font-weight: var(--text-body-medium--font-weight);
  white-space: nowrap;
  transition: filter .18s ease, transform .18s ease;
}

.ui-calendar__day {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 128px;
  overflow: hidden;
  padding: 8px;
  border-radius: 13px;
  background: var(--surface-base);
  transition: background-color .2s ease, box-shadow .2s ease;
}

.ui-calendar__day-number {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  flex: none;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-strong);
  font-size: var(--text-body-2-medium);
  font-weight: var(--text-body-2-medium--font-weight);
}

.ui-calendar__events button {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  min-width: 0;
  min-height: 20px;
  padding: 2px 6px;
  border: 0;
  border-radius: 5px;
  background: #e2efff;
  color: #2860b7;
  text-align: left;
  font-size: var(--text-body-2-medium);
  line-height: 14px;
  font-weight: var(--text-body-2-medium--font-weight);
  transition: filter .15s ease, transform .15s ease;
}

.ui-calendar__events .ui-calendar__more {
  justify-content: flex-start;
  min-height: 17px;
  padding: 0;
  background: transparent;
  color: var(--text-muted);
  font-size: 11px;
}

.ui-calendar__popover {
  position: fixed;
  z-index: 120;
  display: grid;
  gap: 10px;
  width: min(302px, calc(100vw - 24px));
  padding: 10px;
  border: 1px solid var(--border-control);
  border-radius: 20px;
  background: var(--surface-base);
  box-shadow: var(--shadow-panel), 0 16px 34px rgba(17, 24, 39, .08);
  animation: ui-calendar-appear .2s cubic-bezier(.2,.8,.2,1) both;
}

.ui-calendar__popover-head {
  display: flex;
  gap: 1px;
  align-items: flex-start;
  justify-content: space-between;
  min-height: 59px;
  padding: 8px 10px;
  border-radius: 11px;
  background: var(--surface-muted);
}

.ui-calendar__popover-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 8px;
  border-radius: 9px;
  background: var(--surface-muted);
  color: var(--text-main);
  font-size: var(--text-body-2-medium);
  line-height: 18px;
  font-weight: var(--text-body-2-medium--font-weight);
}

.ui-composer-attachments__tile > img {
  inset: 2px;
  width: calc(100% - 4px);
  height: calc(100% - 4px);
  border-radius: 8px;
}

.ui-composer-attachments__tile > .ui-composer-attachments__ring {
  position: absolute;
  z-index: 3;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  fill: none;
  pointer-events: none;
}

.ui-composer-attachments__ring rect {
  stroke: var(--accent-strong);
  stroke-width: 2;
  stroke-dasharray: 100;
  transition: stroke-dashoffset .15s linear;
}

.ui-composer-attachments__tile > small {
  z-index: 4;
  font-size: 9px;
  font-weight: 600;
  opacity: 0;
  filter: blur(4px);
  transform: scale(.8);
  transition: opacity .2s ease, filter .2s ease, transform .2s ease;
}

.ui-composer-attachments__tile > small[data-visible] {
  opacity: 1;
  filter: blur(0);
  transform: scale(1);
}

.ui-composer-attachments__tile > button {
  z-index: 5;
  opacity: 0;
  filter: blur(4px);
  transform: scale(.8);
  transition: opacity .2s ease, filter .2s ease, transform .2s ease;
}

.ui-composer-attachments__tile:not([data-status='uploading']) > button,
.ui-composer-attachments__tile:not([data-status='uploading']) > button:focus-visible {
  opacity: 1;
  filter: blur(0);
  transform: scale(1);
}

.ui-composer__add,
.ui-composer__voice,
.ui-composer__send {
  width: 36px;
  height: 36px;
  transition: background-color var(--motion-fast) ease, color var(--motion-fast) ease, opacity var(--motion-fast) ease, transform var(--motion-fast) var(--motion-ease-soft);
}

.ui-composer-add-menu {
  z-index: 150;
  display: grid;
  gap: 7px;
  width: min(360px, calc(100vw - 24px));
  max-height: calc(100vh - 24px);
  overflow: auto;
  padding: 12px 16px;
  border: 1px solid var(--border-control);
  border-radius: 16px;
  background: var(--surface-base);
  box-shadow: var(--shadow-menu);
}

.ui-composer-add-menu__heading {
  padding: 2px 0 6px;
  color: var(--text-muted);
  font-size: var(--text-body-medium);
  line-height: 19px;
  font-weight: 400;
}

.ui-composer-add-menu__group button {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 36px;
  padding: 4px 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-strong);
  text-align: left;
  transition: background var(--motion-fast) ease, transform var(--motion-fast) var(--motion-ease-soft);
}

.ui-composer-add-menu__group button:hover,
.ui-composer-add-menu__group button:focus-visible {
  background: var(--surface-muted);
  transform: translateX(2px);
}

.ui-composer-add-menu__icon {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: none;
  color: var(--text-muted);
}

.ui-settings-modal {
  width: 100%;
  min-height: 0;
  height: 100%;
  max-height: 100%;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  outline: none;
}

.ui-settings-modal aside h2,
.ui-settings-modal nav button,
.ui-settings-modal__nav-group > span { font-size: var(--text-body-medium); line-height: 20px; font-weight: 500; }

.ui-table :is(th, td),
.ui-data-table__toolbar,
.ui-data-table__filters .ui-select__trigger,
.ui-data-table__search,
.docs-purchase-control,
.docs-purchase-control .ui-select__trigger,
.docs-customer strong,
.docs-table-status {
  transition-property: height, min-height, padding, font-size, line-height, background-color;
  transition-duration: var(--motion-standard);
  transition-timing-function: var(--motion-ease);
}

.ui-task-list {
  width: min(430px, 100%);
  min-width: 0;
  color: var(--text-muted);
  font-size: 14px;
}

.ui-task-list .ui-task-list__tree > .ui-task-list__task {
  display: block;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
}

.ui-task-list .ui-task-list__heading {
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  min-height: 28px;
  padding: 2px 0;
  color: var(--text-muted);
}

.ui-task-list .ui-task-list__heading strong {
  flex: none;
  color: var(--text-main);
  font-size: 14px;
  font-weight: 500;
  line-height: 21px;
}

.ui-task-list .ui-task-list__heading time {
  flex: none;
  margin: 0 0 0 2px;
  color: var(--text-subtle);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.ui-task-list .ui-task-list__events {
  margin: 0 0 5px 9px;
  padding: 0 0 0 12px;
  overflow: hidden;
  border-left: 1px solid var(--border-control);
}

.ui-task-list .ui-task-list__events > li {
  position: relative;
  display: flex;
  align-items: center;
  gap: 5px;
  width: 100%;
  min-width: 0;
  min-height: 28px;
  margin: 0;
  padding: 3px 0 3px 1px;
  border: 0;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 22px;
}

.ui-task-list .ui-task-list__events > li::before {
  position: absolute;
  top: 0;
  left: -12px;
  width: 10px;
  height: 15px;
  border-bottom: 1px solid var(--border-control);
  border-radius: 0 0 0 5px;
  content: '';
}

.ui-task-list__event-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ui-task-list .ui-task-list__resource {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  max-width: min(180px, 45%);
  min-width: 0;
  flex: none;
  padding: 2px 5px;
  border: 1px solid var(--border-subtle);
  border-radius: 5px;
  background: var(--surface-muted);
  color: var(--text-main);
  font-family: var(--font-mono-source), monospace;
  font-size: 10px;
  line-height: 15px;
}

.ui-task-list .ui-task-list__resource span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ui-task-list .ui-task-list__task[data-status='running'] .ui-task-list__heading strong {
  background: linear-gradient(100deg, var(--text-subtle) 5%, var(--text-main) 45%, var(--text-subtle) 85%);
  background-size: 230% auto;
  background-clip: text;
  color: transparent;
  animation: ui-shimmer 2.4s linear infinite;
}

.ui-web-search {
  width: min(560px, 100%);
  min-width: 0;
  color: var(--text-muted);
  font-size: 14px;
}

.ui-web-search .ui-web-search__heading {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
  min-height: 28px;
  padding: 4px 0;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 20px;
}

.ui-web-search__heading > svg {
  flex: none;
  margin-top: 2px;
  color: var(--text-muted);
}

.ui-web-search .ui-web-search__steps {
  position: relative;
  display: block;
  margin: 0 0 0 7px;
  padding: 0 0 0 13px;
  overflow: visible;
  border-left: 1px solid var(--border-control);
  list-style: none;
}

.ui-web-search .ui-web-search__steps::before {
  position: absolute;
  top: -6px;
  left: -1px;
  width: 1px;
  height: 6px;
  background: var(--border-control);
  content: '';
}

.ui-web-search .ui-web-search__steps > .ui-web-search__step {
  position: relative;
  display: block;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: visible;
  border: 0;
  color: var(--text-muted);
}

.ui-web-search .ui-web-search__step::before {
  position: absolute;
  top: 0;
  left: -13px;
  width: 11px;
  height: 16px;
  border-bottom: 1px solid var(--border-control);
  border-radius: 0 0 0 6px;
  content: '';
}

.ui-web-search .ui-web-search__step:last-child::after {
  position: absolute;
  top: 17px;
  bottom: 0;
  left: -14px;
  width: 2px;
  background: var(--surface-base);
  content: '';
}

.ui-web-search .ui-web-search__row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  min-height: 28px;
  padding: 4px 0;
  line-height: 20px;
}

.ui-web-search__icon {
  display: grid;
  place-items: center;
  width: 16px;
  height: 20px;
  flex: none;
  color: var(--text-muted);
}

.ui-web-search .ui-web-search__label {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 14px;
  font-weight: 400;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ui-web-search__label code {
  margin-left: 6px;
  color: var(--text-subtle);
  font-family: var(--font-mono-source), monospace;
  font-size: 11px;
  white-space: nowrap;
}

.ui-web-search .ui-web-search__meta {
  flex: none;
  margin-left: auto;
  color: var(--text-subtle);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
}

.ui-web-search__row[data-active] .ui-web-search__label {
  background: linear-gradient(100deg, var(--text-subtle) 5%, var(--text-main) 45%, var(--text-subtle) 85%);
  background-size: 230% auto;
  background-clip: text;
  color: transparent;
  animation: ui-shimmer 2.4s linear infinite;
}

.ui-web-search .ui-web-search__source-branch {
  position: relative;
  margin: -1px 0 3px 7px;
  padding: 0 0 0 16px;
  overflow: visible;
  border-left: 1px solid var(--border-control);
}

.ui-web-search .ui-web-search__source-branch::before {
  position: absolute;
  top: 0;
  left: -1px;
  width: 12px;
  height: 15px;
  border-bottom: 1px solid var(--border-control);
  border-radius: 0 0 0 6px;
  content: '';
}

.ui-web-search .ui-web-search__source-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0;
  min-height: 28px;
  padding: 1px 0;
  border: 0;
  background: transparent;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 20px;
}

.ui-web-search .ui-web-search__source-trigger > svg {
  margin-left: 5px;
  color: var(--text-subtle);
  transition: transform 250ms ease;
}

.ui-web-search .ui-web-search__mark {
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  flex: none;
  margin-left: -5px;
  border: 1px solid var(--border-subtle);
  border-radius: 50%;
  background: var(--surface-base);
  color: var(--text-muted);
  transition: transform 170ms ease, box-shadow 170ms ease;
}

.ui-web-search .ui-web-search__mark:hover {
  z-index: 2;
  transform: translateY(-4px) scale(1.2);
  box-shadow: var(--shadow-control);
}

.ui-web-search .ui-web-search__source-links {
  display: block;
  margin: 0;
  padding: 0 0 3px;
  overflow: hidden;
  list-style: none;
}

.ui-web-search .ui-web-search__source-links > li {
  display: block;
  min-height: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.ui-web-search .ui-web-search__source-links a,
.ui-web-search .ui-web-search__source-static {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 27px;
  padding: 3px 5px;
  border-radius: 7px;
  color: var(--text-muted);
  font-size: 13px;
}

.ui-web-search__source-title {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ui-web-search .ui-web-search__source-links small {
  flex: none;
  color: var(--text-subtle);
  font-size: 11px;
}

.ui-web-search .ui-web-search__restart {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  margin-top: 18px;
  padding: 5px 11px;
  border: 1px solid var(--border-control);
  border-radius: 9px;
  background: var(--surface-base);
  color: var(--text-main);
  box-shadow: var(--shadow-control);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
}

.ui-web-search .ui-web-search__restart:hover {
  background: var(--surface-muted);
  box-shadow: var(--shadow-panel);
  transform: translateY(-1px);
}

.ui-notification-center {
  width: min(430px, 100%);
  min-width: 0;
  padding: 16px 15px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 22px;
  background: var(--surface-base);
  box-shadow: var(--shadow-control);
}

.ui-notification-center header h2 {
  color: var(--text-strong);
  font-size: 18px;
  font-weight: 500;
  line-height: 26px;
}

.ui-notification-center header p {
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 20px;
}

.ui-notification-center header button {
  min-height: 32px;
  padding: 0 11px;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent-label);
  font-size: 14px;
  font-weight: 500;
}

.ui-notification-center__list {
  display: grid;
  align-content: start;
  gap: 8px;
  max-height: 516px;
  margin-inline: -8px;
  overflow-y: auto;
  padding: 7px;
  border-radius: 13px;
  background: var(--surface-muted);
  scrollbar-color: var(--border-control) transparent;
  scrollbar-width: none;
}

.ui-notification-center__item {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 0;
  padding: 12px;
  border: 0;
  border-radius: 12px;
  background: var(--surface-base);
}

.ui-notification-center__copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ui-notification-center__copy > .ui-notification-center__headline {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-top: 0;
}

.ui-notification-center__copy strong {
  display: block;
  overflow: hidden;
  color: var(--text-strong);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ui-notification-center__copy p {
  margin: 0;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 20px;
}

.ui-notification-center__copy .ui-notification-center__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.ui-notification-center__actions button {
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid var(--border-control);
  border-radius: 8px;
  background: var(--surface-base);
  color: var(--text-main);
  box-shadow: var(--shadow-control);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  transition: background-color 160ms ease, transform 160ms ease;
}

.ui-notification-center__actions button[data-variant='primary'] {
  border-color: var(--accent-strong);
  background: var(--accent-strong);
  color: var(--on-accent);
}

.ui-notification-center__actions button[data-variant='secondary'] {
  border-color: var(--border-control);
  background: var(--surface-base);
  color: var(--text-main);
}

.ui-notification-center__actions button[data-variant='danger'] {
  border-color: var(--danger-strong);
  background: var(--danger-strong);
  color: white;
}

.ui-notification-center__meta {
  gap: 8px;
  min-height: 20px;
  flex: none;
  color: var(--text-subtle);
  font-size: 12px;
  line-height: 20px;
}

.ui-notification-center__meta button {
  width: 8px;
  height: 8px;
  min-height: 8px;
  flex: none;
  padding: 0;
  border: 0;
  box-shadow: none;
}

.ui-questionnaire {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: min(648px, 100%);
  padding: 12px;
  border: 0;
  border-radius: 20px;
  background: var(--surface-base);
  box-shadow: 0 4px 2px rgb(0 0 0 / 2%), 0 1px 1px rgb(0 0 0 / 5%);
}

.ui-questionnaire__close {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--surface-muted);
  color: var(--text-muted);
}

.ui-questionnaire__question h2 {
  min-height: 20px;
  margin: 0 28px 10px 2px;
  color: var(--text-strong);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

.ui-questionnaire__options > label,
.ui-questionnaire__other-row {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 60px;
  padding: 9px 19px 9px 11px;
  border: 1px solid var(--border-control);
  border-radius: 16px;
  background: var(--surface-base);
  transition: background-color 150ms ease, border-color 150ms ease;
}

.ui-questionnaire__options > label:hover,
.ui-questionnaire__options > label[data-selected],
.ui-questionnaire__other-row:hover,
.ui-questionnaire__other-row:focus-within {
  border-color: var(--border-control);
  background: var(--surface-raised);
  transform: none;
}

.ui-questionnaire__choice {
  position: absolute;
  width: 1px !important;
  height: 1px !important;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.ui-questionnaire__option-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 0;
}

.ui-questionnaire__options > label > .ui-questionnaire__option-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0;
}

.ui-questionnaire__options strong {
  color: var(--text-strong);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

.ui-questionnaire__options small {
  color: var(--text-muted);
  font-size: 14px;
  font-weight: 400;
  line-height: 20px;
}

.ui-questionnaire__check {
  display: grid;
  width: 16px;
  height: 16px;
  flex: none;
  place-items: center;
  border: 1px solid var(--border-strong);
  border-radius: 4px;
  background: var(--surface-base);
  color: transparent;
  box-shadow: var(--shadow-control);
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, transform 150ms ease;
}

.ui-questionnaire__options > label > .ui-questionnaire__check {
  display: grid;
  min-width: 16px;
  flex: none;
  gap: 0;
}

.ui-questionnaire__options > label[data-selected] .ui-questionnaire__check,
.ui-questionnaire__other-row[data-selected] .ui-questionnaire__check {
  border-color: var(--accent-strong);
  background: var(--accent-strong);
  color: white;
  transform: scale(1.04);
}

.ui-questionnaire__other {
  width: 100%;
  max-width: none;
  height: 20px;
  margin: 0;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--text-strong);
  font-size: 14px;
  line-height: 20px;
}

.ui-questionnaire__other-check {
  display: grid;
  flex: none;
  place-items: center;
  padding: 4px 0;
  cursor: pointer;
}

.ui-questionnaire footer {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-height: 34px;
  margin-top: 0;
  padding-top: 2px;
}

.ui-questionnaire footer > button {
  min-height: 32px;
  padding: 0 8px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

.ui-questionnaire footer > button:disabled {
  border-color: var(--border-control);
  background: var(--surface-muted);
  color: var(--text-subtle);
  opacity: 1;
}

.ui-questionnaire footer .ui-questionnaire__next {
  border: 0;
  background: var(--accent-strong);
  color: white;
}

.ui-notification {
  position: relative;
  align-items: flex-start;
  gap: 12px;
  width: min(520px, 100%);
  min-height: 0;
  padding: 16px 44px 16px 16px;
  border: 1px solid var(--border-control);
  border-radius: 16px;
  background: var(--surface-base);
  box-shadow: var(--shadow-control);
}

.ui-notification__presence {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 12px;
  height: 12px;
  border: 2px solid var(--surface-base);
  border-radius: 50%;
  background: #9ccf19;
}

.ui-notification__content {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 4px;
}

.ui-notification__heading {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
}

.ui-notification__content strong {
  color: var(--text-strong);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

.ui-notification__content p {
  margin: 0;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 20px;
}

.ui-notification__actions button {
  min-height: 32px;
  padding: 0 10px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

.ui-notification__actions .ui-notification__primary {
  border-color: var(--accent-strong);
  background: var(--accent-strong);
  color: white;
}

.ui-notification__close {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 20px;
  height: 20px;
  padding: 0;
  border-radius: 50%;
}

.ui-notification__countdown {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 3px;
  transform-origin: left;
  border-radius: 0 0 16px 16px;
  background: var(--accent-strong);
  animation-name: ui-notification-countdown;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

.ui-notification-viewport {
  position: fixed;
  z-index: var(--layer-notification);
  display: flex;
  width: min(520px, calc(100vw - 32px));
  max-height: calc(100dvh - 32px);
  flex-direction: column;
  gap: 10px;
  overflow: visible;
  pointer-events: none;
}

.ui-chart-card {
  container-type: inline-size;
  padding: 16px 16px 12px;
  border: 0;
  border-radius: 16px;
  background: color-mix(in srgb, var(--surface-base) 97%, var(--text-main));
  box-shadow: none;
}

.ui-chart-card--activity-rings,
.ui-chart-card--days,
.ui-chart-card--sleep { display: flex; flex-direction: column; height: 330px; min-height: 0; padding: 10px; border-radius: 20px; }

.ui-chart-card__plot path[fill='none']:not([stroke-dasharray]) {
  stroke-dasharray: 1000;
  animation: ui-chart-draw 900ms cubic-bezier(.2,.75,.25,1) both;
}
